    [Theory]
    [MemberData(nameof(OriginalFrameRows))]
    public void Canonical_entity_birth_and_framing_match_original(int mode, int difficulty, int type, int seed,
        string expectedGrid, string expectedRandom, int expectedNpcs, int expectedProjectiles, string bodyData)
    {
        var workspace = new Workspace(160, 120);
        var npcs = new RuntimeNpcStore(); var projectiles = new RuntimeProjectileStore();
        npcs.SetVanillaSpawnContextSource(() => new VanillaNpcSpawnContext(difficulty + 1, 0, false) { WorldDifficulty = difficulty + 1 });
        npcs.SetVanillaSpawnWetCollisionSource((x, y, width, height) => false);
        workspace.AttachEntityEffects(new WorldGenerationEntityEffects1458(npcs, projectiles, mode == 2), 0, difficulty + 1);
        workspace.InitializeVanillaGenerationSolidity(); workspace.SetVanillaGenerationSolid(VanillaTileIds.Hive, true);
        Assert.True(workspace.TileStore.TryAttachTileEntities([], 1000));
        for (int x = 0; x < 160; x++) for (int y = 30; y < 120; y++)
            workspace.TileStore.Set(x, y, new WorldTile { Type = 1, Flags = WorldTileFlags.Active });
        int size = type == 231 ? 3 : 2;
        for (int x = 0; x < size; x++) for (int y = 0; y < size; y++)
            workspace.TileStore.Set(40 + x, 20 + y, new WorldTile { Type = (ushort)type, Flags = WorldTileFlags.Active, FrameX = (short)(x * 18), FrameY = (short)(y * 18) });
        var random = new RandomAdapter(seed);
        new GenerationTileFraming1458(workspace.TileStore, random, workspace, useWorldGenerationSolidity: true)
        { SourceGameMenu = type != 231 }.TileFrame(40, 20);
        Assert.Equal(expectedGrid, GridHash(workspace)); Assert.Equal(expectedRandom, random.Hash());
        Assert.Equal(expectedNpcs, npcs.ActiveCount);
        using var bodies = JsonDocument.Parse(Convert.FromBase64String(bodyData));
        foreach (var e in bodies.RootElement.EnumerateArray())
        {
            Assert.True(npcs.TryGetActive((byte)e.GetProperty("slot").GetInt32(), out var n));
            Assert.Equal(e.GetProperty("type").GetInt32(), n.Type); Assert.Equal(e.GetProperty("x").GetSingle(), n.PositionX); Assert.Equal(e.GetProperty("y").GetSingle(), n.PositionY);
            Assert.Equal(e.GetProperty("life").GetInt32(), n.Simulation.Life); Assert.Equal(e.GetProperty("lifeMax").GetInt32(), n.Simulation.LifeMax); Assert.Equal(e.GetProperty("timeLeft").GetInt32(), n.Simulation.TimeLeft);
            Assert.Equal(e.GetProperty("target").GetInt32(), n.Target); Assert.Equal(e.GetProperty("ai3").GetSingle(), n.Ai.Ai3); Assert.Equal(e.GetProperty("spawnNeedsSyncing").GetBoolean(), npcs.HasPendingBirth(n.Handle));
        }
        bool hasProjectile = projectiles.TryGetActive(0, out var p);
        Assert.Equal(expectedProjectiles == 1, hasProjectile);
        if (hasProjectile) { Assert.Equal(655, p.Type.Value); Assert.Equal(0, p.Spawner); Assert.Equal(640.5f, p.PositionX); Assert.Equal(320.5f, p.PositionY); Assert.True(projectiles.TryGetLifecycle(p.Handle, out var life)); Assert.Equal(3600, life.TimeLeft); }
        Assert.Empty(workspace.CaptureGeneratedNpcs().TownNpcs); Assert.Empty(workspace.CaptureGeneratedNpcs().PersistentNpcs);
    }

