    [Theory]
    [MemberData(nameof(OriginalTownRows))]
    public void Town_slot_allocation_precedes_identity_and_retains_pending_birth(int mode, int seed, bool good,
        int occupied, int type, int expectedSlot, string nameHash, string expectedRandom, string expectedNpcBytes,
        int variation, int life, int lifeMax, int timeLeft)
    {
        var workspace = new Workspace(96, 96); Assert.True(workspace.TrySetSpawn(48, 48));
        var npcs = new RuntimeNpcStore();
        npcs.SetVanillaSpawnContextSource(() => new VanillaNpcSpawnContext(good ? 2 : 1, 0, good) { WorldDifficulty = good ? 2 : 1 });
        npcs.SetVanillaSpawnWetCollisionSource((x, y, width, height) => false);
        workspace.AttachEntityEffects(new WorldGenerationEntityEffects1458(npcs, new RuntimeProjectileStore(), mode == 2));
        for (int i = 0; i < occupied; i++) Assert.True(npcs.TrySpawn((byte)i, new NpcStateUpdate(1, 1, 0, 0, 0, 0, 255, default, NpcSimulationState.Initial), out _));
        var random = new RandomAdapter(seed); int resolverCalls = 0;
        if (type == 22) StartingGuidePass1458.Instance.Execute(new Context(workspace, random, (ulong)seed));
        else Assert.True(workspace.TrySpawnGeneratedTownNpc(new(type), 768, 768, true, 48, 48, random, () => { resolverCalls++; return new(string.Empty, 0); }));
        var actual = workspace.CaptureGeneratedNpcs();
        Assert.Equal(expectedSlot < 200 ? 1 : 0, actual.TownNpcs.Length);
        Assert.Equal(type == 37 && expectedSlot < 200 ? 1 : 0, resolverCalls);
        if (expectedSlot < 200)
        {
            Assert.True(npcs.TryGetActive((byte)expectedSlot, out var n));
            Assert.Equal(759f, n.PositionX); Assert.Equal(728f, n.PositionY); Assert.Equal(life, n.Simulation.Life); Assert.Equal(lifeMax, n.Simulation.LifeMax); Assert.Equal(timeLeft, n.Simulation.TimeLeft);
            Assert.Equal(mode == 2, npcs.HasPendingBirth(n.Handle)); Assert.Equal(48, n.Simulation.HomeTileX); Assert.Equal(48, n.Simulation.HomeTileY); Assert.True(n.Simulation.Homeless);
            Assert.Equal(nameHash, Digest(Encoding.UTF8.GetBytes(actual.TownNpcs[0].GivenName))); Assert.Equal(variation, actual.TownNpcs[0].TownNpcVariationIndex);
        }
        Assert.Equal(expectedRandom, random.Hash());
        using var stream = new MemoryStream();
        Assert.Equal(WorldFileNpcEncodeResult.Encoded, WorldFileNpcEncoder.TryEncode(actual, new(1000, 1000, 1000, 1000, 1000, 100000), stream, out _));
        Assert.Equal(expectedNpcBytes, Digest(stream.ToArray()));
    }

    private static string Digest(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes));
    private static string GridHash(Workspace workspace)
    {
        var b = new StringBuilder(); WorldTileFlags[] flags = [WorldTileFlags.WireRed, WorldTileFlags.WireBlue, WorldTileFlags.WireGreen, WorldTileFlags.WireYellow, WorldTileFlags.Actuator, WorldTileFlags.Inactive, WorldTileFlags.InvisibleBlock, WorldTileFlags.FullbrightBlock, WorldTileFlags.InvisibleWall, WorldTileFlags.FullbrightWall];
        for (int x = 0; x < workspace.WidthTiles; x++) for (int y = 0; y < workspace.HeightTiles; y++)
        { var t = workspace.TileStore.Get(x, y); b.Append(t.IsActive ? 1 : 0).Append(',').Append(t.Type).Append(',').Append(t.Wall).Append(',').Append(t.FrameX).Append(',').Append(t.FrameY).Append(',').Append(t.LiquidAmount).Append(',').Append((int)t.LiquidKind).Append(',').Append(t.IsHalfBrick ? 1 : 0).Append(',').Append(t.SourceSlope).Append(',').Append(t.TileColor).Append(',').Append(t.WallColor); foreach (var f in flags) b.Append(',').Append((t.Flags & f) != 0 ? 1 : 0); b.Append(';'); }
        return Digest(Encoding.UTF8.GetBytes(b.ToString()));
    }
    private sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public int Next() => random.Next(); public int Next(int maxValue) => random.Next(maxValue); public int Next(int minValue, int maxValue) => random.Next(minValue, maxValue); public double NextDouble() => random.NextDouble(); public void NextBytes(byte[] bytes) => random.NextBytes(bytes);
        public string Hash() { const BindingFlags all = BindingFlags.Instance | BindingFlags.NonPublic; using var stream = new MemoryStream(); using (var writer = new BinaryWriter(stream)) { writer.Write((uint)typeof(VanillaUnifiedRandom1458).GetField("inext", all)!.GetValue(random)!); foreach (int v in (int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray", all)!.GetValue(random)!) writer.Write(v); } return Digest(stream.ToArray()); }
    }
    private sealed class Context(Workspace workspace, IWorldGenerationVanillaRandom random, ulong seed) : IWorldGenerationContext
    { public WorldGenerationRequest Request => new(Provider1458.GeneratorId, "Source town allocation", seed, 96, 96); public IWorldGenerationWorkspace Workspace => workspace; public IWorldGenerationMetadataWorkspace Metadata => workspace; public IWorldGenerationRandom Random => throw new NotSupportedException(); public IWorldGenerationVanillaRandom VanillaRandom => random; public CancellationToken CancellationToken => default; public void ReportProgress(double fraction, string? message = null) { } }
